"""runtime.parsing: generated by the graph.py split (P1)."""

from __future__ import annotations

import hashlib
import re
from typing import Any, Iterator


def _attempt_digest(text: str) -> str:
    return hashlib.sha256((text or "").encode("utf-8", "replace")).hexdigest()[:16]


def _as_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    return str(value or "").strip().lower() in ("1", "true", "yes", "on")


def _yaml_str(value: Any) -> str:
    import yaml as _yaml
    return _yaml.safe_dump(value, sort_keys=False) if isinstance(value, dict) else str(value)


_FENCED_DOCUMENT = re.compile(
    r"```(?:json|yaml|yml)\s*\n(?P<body>.*?)```", re.IGNORECASE | re.DOTALL
)


def document_candidates(text: str) -> Iterator[str]:
    """Yield the response itself, then any fenced JSON/YAML block inside it.

    Models wrap a whole answer in ```yaml fences and add a prose preamble even
    when told not to. The response is always tried first, so a clean answer is
    unaffected; the fenced bodies are a compatibility fallback, never a rewrite
    of the model's YAML.
    """
    yield text
    for match in _FENCED_DOCUMENT.finditer(text or ""):
        yield match.group("body")


def parse_yaml_mapping(text: str) -> dict | None:
    """Parse one model reply into a mapping, tolerating a fence and a preamble.

    A bare ``yaml.safe_load`` is not enough: the reply may carry a prose
    sentence and a ```yaml fence, and a stage that silently loses its answer
    that way is worse than a loud parse failure (observed 2026-09-29, twice).
    """
    import yaml as _yaml

    for candidate in document_candidates(text or ""):
        if not candidate.strip():
            continue
        try:
            data = _yaml.safe_load(candidate)
        except _yaml.YAMLError:
            continue
        if isinstance(data, dict):
            return data
    return None
